def split_task(reviews):
    """Turn a list of reviews into one subtask per review."""
    subtasks = []
    for index, review_text in enumerate(reviews):
        subtasks.append({
            "subtask_id": index,
            "review_text": review_text,
        })
    return subtasks


reviews = [
    "Battery life is great, but the screen scratches easily.",
    "Fast delivery, though the box arrived a bit dented.",
    "Works fine, nothing special, does what it says.",
]
subtasks = split_task(reviews)
print(subtasks)

def merge_results(results):
    counts = {"positive": 0, "mixed": 0, "neutral": 0}
    for item in results:
        counts[item["sentiment"]] += 1

    total = len(results)
    summary = (
        f"Out of {total} reviews, {counts['positive']} were positive, "
        f"{counts['mixed']} were mixed, and {counts['neutral']} were neutral."
    )
    return summary


final_summary = merge_results(results)
print(final_summary)

def judge(review_text, answer_a, answer_b):
    """Very small judge: prefer 'mixed' when the two answers differ,
    since mixed usually captures both sides fairly."""
    if answer_a == answer_b:
        return answer_a
    return "mixed"


def merge_with_conflict_check(review_text, agent_a_result, agent_b_result):
    if agent_a_result == agent_b_result:
        return {"sentiment": agent_a_result, "resolved_by": "agreement"}

    final = judge(review_text, agent_a_result, agent_b_result)
    return {"sentiment": final, "resolved_by": "judge"}


outcome = merge_with_conflict_check(
    "Battery life is great, but the screen scratches easily.",
    "positive",
    "mixed",
)
print(outcome)
